/*    implied euro */

#define NRANSI
#define ITMAX 500 
#define EPS 3.0e-8



#define E               2.718281828
#define PI              3.14159265359
#define B1              0.4361836
#define B2             -0.1201676
#define B3              0.937298
#define B4             -1.821255978
#define B5              1.330274429
#define A               0.33267
#define RT2PI           2.506628275

/* Lifted without modifications from /research/joy/rms/rms1.4 */
static double  Power( double a, int b) {
/* raises a to the b Power, returns result as double */

  double c;
  int i;
  c = 1;
  for (i=1; i<=b; i++)
  c = c * a;
  return c;
}


/* Lifted without modifications from /research/joy/rms/rms1.4 */
double  CalcBseries( double in_val) {

  double out_val;
  out_val =   B1*(1/(1+(A*fabs(in_val))))
     + B2 * (Power(1/(1+(A*fabs(in_val))),2))
     + B3 * (Power(1/(1+(A*fabs(in_val))),3));
  return out_val;
}



/* Lifted without modifications from /research/joy/rms/rms1.4 */
double  CalcND1( double D1, double Bseries1) {

  double ND1;
   if ( D1 > 40.)
      return(1.0);
   else if ( D1 < -40.)
      return(0.0);

   ND1 = 1-(1/sqrt(2 * PI) * exp((-D1*D1)/2) * Bseries1);
   if (D1<0)
       ND1 = 1 - ND1;
   return ND1;
}

/* Lifted from /research/joy/rms/rms1.4 -- MODIFIED TO ALLOW FOR ARBITRARY YIELD. */ 
double  CalcCall( double IntRt, double Yield, double Time, double FwdPr, double ND1, double FixPr, double ND2) {

  double Call;
  Call = exp(-Yield * Time) * FwdPr * ND1 - exp(-IntRt * Time) * FixPr * ND2;
  return Call;
}

/* Lifted from /research/joy/rms/rms1.4 -- MODIFIED TO ALLOW FOR ARBITRARY YIELD. */ 
static double  CalcPut( double IntRt, double Yield, double Time, double FwdPr, double FixPr, double NegND1, double NegND2) {

  double Put;

  Put = exp(-IntRt * Time) * FixPr * NegND2  - exp(-Yield * Time) * FwdPr * NegND1;
  return Put;
}

/* Lifted from /research/joy/rms/rms1.4 -- MODIFIED TO ALLOW FOR ARBITRARY YIELD. */ 
double  bscall0( double s, double k, double time, double r, double q, double vol1  ) {

  double d1, d2, Bseries1, Bseries2, call, Nd1, Nd2;

  d1 = (log(s/k)+(r - q + vol1*vol1/2)* time)/(vol1 * sqrt(time));
  d2 = d1-(vol1*sqrt(time));

  /* d1= CalcD1(mo_qty,s,k,vol1,time); d2=CalcD2(mo_qty,s,k,vol1,time); */

    Bseries1 = CalcBseries(d1);
    Bseries2 = CalcBseries(d2);
    Nd1= CalcND1(d1, Bseries1);
    Nd2 = CalcND1(d2, Bseries2);
    call = CalcCall(r,q,time,s,Nd1,k,Nd2);
  return( call );
}

/* Lifted from /research/joy/rms/rms1.4 -- MODIFIED TO ALLOW FOR ARBITRARY YIELD. */ 
double  bsput0( double s, double k, double time, double r, double q, double vol1  ) {

  double negd1, negd2, Bseries1, Bseries2, put, Nd1, Nd2;

    negd1 = (log(s/k)+(r - q + vol1*vol1/2)* time)/(-vol1 * sqrt(time));
    negd2 = vol1*sqrt(time) + negd1;

    Bseries1 = CalcBseries(negd1);
    Bseries2 = CalcBseries(negd2);
    Nd1= CalcND1(negd1, Bseries1);
    Nd2 = CalcND1(negd2, Bseries2);

    put = k * exp(-r*time) * Nd2 - s *  exp(-r*time) * Nd1;
    return( put );
}


/* Lifted from /research/joy/rms/rms1.4 
  -- MODIFIED TO ALLOW FOR ARBITRARY YIELD 
  -- also days2expiry variable has been
  substituted with tenor. */ 

double bseuro(int pc, double s, double k, double amount, double tenor, double vol1, double r, double q  ){
  if( pc == 1)
    return(amount * bscall0(s, k, tenor, r, q, vol1  ) );   // call
  else if( pc == 0)
    return(amount * bsput0( s, k, tenor, r, q, vol1  ) );   // put
  else if( pc == 2)        // straddle = call + put
 return(amount * (bsput0( s, k, tenor, r, q, vol1  )+  \
                  bscall0(s, k, tenor, r, q, vol1  )  ) );

  else{
    do_error("Error in bseuro\n");
  }
  return((double) FAILURE);
}



/* Modified from Numer. Recip. */
double zbrent_e(double (*bseuro)(int, double, double, double, double, double, double, double),
      double x1, double x2, double tol,
      int putcallind, double spot, double strike, double amount, double tenor, double actual_premium,
      double rate, double yield, int maxiter)
{
 int iter;
 double a=x1,b=x2,c=x2,d,e,min1,min2;
 double fa=(*bseuro)(putcallind, spot, strike, amount, tenor, a, rate, yield)-actual_premium,
        fb=(*bseuro)(putcallind, spot, strike, amount, tenor, b, rate, yield)-actual_premium,
        fc,p,q,r,s,tol1,xm;

 if ((fa > 0.0 && fb > 0.0) || (fa < 0.0 && fb < 0.0)){
   // do_error("Root must be bracketed in zbrent_e");
  return -1.0;  // maxvol too small
  }
 fc=fb;
 for (iter=1;iter<= ( maxiter <= ITMAX ? maxiter : ITMAX) ;iter++) {

  if ((fb > 0.0 && fc > 0.0) || (fb < 0.0 && fc < 0.0)) {
   c=a;
   fc=fa;
   e=d=b-a;
  }
  if (fabs(fc) < fabs(fb)) {
   a=b;
   b=c;
   c=a;
   fa=fb;
   fb=fc;
   fc=fa;
  }
  tol1=2.0*EPS*fabs(b)+0.5*tol;
  xm=0.5*(c-b);
  if (fabs(xm) <= tol1 || fb == 0.0) return b;
  if (fabs(e) >= tol1 && fabs(fa) > fabs(fb)) {
   s=fb/fa;
   if (a == c) {
    p=2.0*xm*s;
    q=1.0-s;
   } else {
    q=fa/fc;
    r=fb/fc;
    p=s*(2.0*xm*q*(q-r)-(b-a)*(r-1.0));
    q=(q-1.0)*(r-1.0)*(s-1.0);
   }
   if (p > 0.0) q = -q;
   p=fabs(p);
   min1=3.0*xm*q-fabs(tol1*q);
   min2=fabs(e*q);
   if (2.0*p < (min1 < min2 ? min1 : min2)) {
    e=d;
    d=p/q;
   } else {
    d=xm;
    e=d;
   }
  } else {
   d=xm;
   e=d;
  }
  a=b;
  fa=fb;
  if (fabs(d) > tol1)
   b += d;
  else
   b += SIGN(tol1,xm);
  fb=(*bseuro)(putcallind, spot, strike, amount, tenor, b, rate, yield)-actual_premium;
 }
 //do_error("Maximum number of iterations exceeded in zbrent_e");
 return -2.0;
}
